#include <iostream>
#include <vector>

int main() {
    std::vector<int> v1 = {10, 20, 30};
    std::vector<int> v2 = v1; // Copy constructor

    std::cout << "v1 == v2: " << std::boolalpha << (v1 == v2) << "\n";

    v2[1] = 99; // Modify element using [] lvalue
    std::cout << "After modification:\n";
    std::cout << "v1 != v2: " << (v1 != v2) << "\n";
    std::cout << "v2.at(1): " << v2.at(1) << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <stdexcept>

int main() {
    std::vector<int> numbers = {10, 20, 30};

    try {
        std::cout << "Accessing element at index 1: " << numbers.at(1) << "\n";
        std::cout << "Attempting to access index 5...\n";
        std::cout << numbers.at(5) << "\n";
        std::cout << "This line will never execute!\n";
    } catch (const std::out_of_range& ex) {
        std::cout << "Exception caught: " << ex.what() << "\n";
    }

    std::cout << "Program continued successfully after catch block.\n";
    return 0;
}
